void AStateController::Finish(){Finished=true;auto Root=MakeShared<FJsonObject>();Root->SetStringField(TEXT("engine"),FEngineVersion::Current().ToString());Root->SetStringField(TEXT("phase"),TestPhase);Root->SetBoolField(TEXT("no_animation_plugin"),true);Root->SetStringField(TEXT("input"),TEXT("Project API and native streamed-world consumers; no human/device claim"));TArray<TSharedPtr<FJsonValue>> C,F;for(const auto& S:Checks)C.Add(MakeShared<FJsonValueString>(S));for(const auto& S:Failures)F.Add(MakeShared<FJsonValueString>(S));Root->SetArrayField(TEXT("checks"),C);Root->SetArrayField(TEXT("failures"),F);FString Text;FJsonSerializer::Serialize(Root,TJsonWriterFactory<>::Create(&Text));FFileHelper::SaveStringToFile(Text,*Report,FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM);FPlatformMisc::RequestExitWithStatus(false,Failures.Num()?1:0);}
